<template>
  <section class="cost-panel" v-loading="loading">
    <el-alert v-if="error" :title="error" type="error" :closable="false" />
    <template v-if="context">
      <el-descriptions border :column="2"><el-descriptions-item label="单据">{{ context.target?.number }} · {{ kindLabel }}</el-descriptions-item><el-descriptions-item label="费用维护">{{ context.fee ? (context.fee.state==='confirmed'?'已确认':'估算') : '未维护' }}<span v-if="context.fee?.amount!=null && Number(context.fee.amount)===0"> · 已明确登记为零</span></el-descriptions-item></el-descriptions>
      <el-alert v-if="refreshPending" title="单据版本已变化，当前表单有未保存内容。保存或手动刷新后可读取最新数据。" type="warning" :closable="false" class="spaced"><template #default><el-button link @click="load">刷新最新数据</el-button></template></el-alert>
      <el-alert v-if="!refreshPending && dirty" title="有未保存的费用或结算登记输入。" type="info" :closable="false" class="spaced" />
      <el-alert v-if="context.target?.fee_block_reason" :title="context.target.fee_block_reason" type="warning" :closable="false" class="spaced" />
      <section v-if="context.freight_quote_reference" class="spaced"><h4>批次冻结报价参考</h4><p>{{context.freight_quote_reference.channel_name}} · v{{context.freight_quote_reference.quote_sequence}} · {{context.freight_quote_reference.billing_basis==='container'?`${context.freight_quote_reference.container_type}，按柜`:'按方'}} · 单价 {{context.freight_quote_reference.unit_price}} · {{context.freight_quote_reference.prices_include_tax?'含税':'未税'}}（税点 {{context.freight_quote_reference.tax_percent}}%）</p><p>按已保存计费资料计算的参考金额：{{context.freight_quote_reference.reference_amount ?? '待维护计费体积'}}<span v-if="context.freight_quote_reference.quantity!=null"> · 计费量 {{context.freight_quote_reference.quantity}}</span></p><p class="hint">参考金额用于核对报价；实际费用以本页维护并保存的费用金额为准。</p></section>
      <section v-if="context.settlement?.payment_terms" class="spaced"><h4>供应商账期约定</h4><p>{{context.settlement.payment_terms.start_label || '未记录起算方式'}} · {{context.settlement.payment_terms.days==null?'账期未维护':`${context.settlement.payment_terms.days} 天`}} · 参考到期日 {{context.settlement.payment_terms.due_date || '待确定'}}</p><p class="hint">{{context.settlement.payment_terms.message}}</p></section>
      <div v-if="editable" class="fee-form">
        <h4>费用维护</h4>
        <div class="grid"><el-form-item label="费用金额"><el-input :disabled="busy||loading" v-model="fee.amount" inputmode="decimal" placeholder="例如 0.0000" /></el-form-item><el-form-item label="费用状态"><el-select :disabled="busy||loading" v-model="fee.state"><el-option label="估算" value="estimated"/><el-option label="已确认" value="confirmed"/></el-select></el-form-item>
        <el-form-item label="分摊方式"><el-select :disabled="busy||loading" v-model="fee.method"><el-option label="按体积" value="volume"/><el-option label="按重量" value="weight"/><el-option label="体积 + 重量" value="mixed"/></el-select></el-form-item><el-form-item v-if="fee.method==='mixed'" label="体积分摊比例 %"><el-input :disabled="busy||loading" v-model="fee.volume_percent" inputmode="decimal" /></el-form-item>
        <el-form-item v-if="kind!=='shipment'" label="计费体积 m³（记录用途）"><el-input :disabled="busy||loading" v-model="fee.billed_cbm" inputmode="decimal" placeholder="可选；不会自动计算费用" /></el-form-item><el-form-item label="原因（必填）"><el-input :disabled="busy||loading" v-model="fee.reason" /></el-form-item></div>
        <el-form-item label="备注"><el-input :disabled="busy||loading" v-model="fee.notes" type="textarea" /></el-form-item>
        <div class="table-scroll"><el-table :data="measurements" border><el-table-column label="商品图片" width="112"><template #default="{row}"><DocumentProductImageV2 :image-path="row.image_preview_url || ''" :alt="`${row.sku || ''} 商品图片`"/></template></el-table-column><el-table-column label="SKU" min-width="190"><template #default="{row}"><DocumentSkuV2 :sku="row.sku" :legacy-sku-code="row.legacy_sku_code"/></template></el-table-column><el-table-column prop="product_name" label="商品"/><el-table-column prop="quantity" label="数量"/><el-table-column label="本行总体积 m³"><template #default="{row}"><el-input :disabled="busy||loading" v-model="row.volume_cbm" inputmode="decimal" placeholder="补充本行实测总体积"/></template></el-table-column><el-table-column label="本行总重量 kg"><template #default="{row}"><el-input :disabled="busy||loading" v-model="row.weight_kg" inputmode="decimal" placeholder="补充本行实测总重量"/></template></el-table-column></el-table></div>
        <p class="hint">体积和重量均为该商品行总量（含该行全部数量）；录入实测总量会覆盖自动计量值。金额最多 4 位小数，计量最多 6 位。</p>
        <el-button type="primary" :disabled="busy||!canWrite" :loading="busy" @click="saveFee">保存费用</el-button>
      </div>
      <div v-else class="spaced"><el-tag type="info">只读</el-tag></div>
      <div class="table-scroll"><h4>费用分摊</h4><el-table :data="context.fee?.allocations||[]" border empty-text="费用尚未维护"><el-table-column label="商品图片" width="112"><template #default="{row}"><DocumentProductImageV2 :image-path="row.image_preview_url || ''" :alt="`${row.sku || ''} 商品图片`"/></template></el-table-column><el-table-column label="SKU" min-width="190"><template #default="{row}"><DocumentSkuV2 :sku="row.sku" :legacy-sku-code="row.legacy_sku_code"/></template></el-table-column><el-table-column prop="quantity" label="数量"/><el-table-column prop="volume_cbm" label="体积 m³"/><el-table-column prop="weight_kg" label="重量 kg"/><el-table-column prop="amount" label="分摊金额"/></el-table></div>
      <div v-if="context.fee_history?.length" class="table-scroll"><h4>费用历史</h4><el-table :data="context.fee_history" border><el-table-column label="时间"><template #default="{row}">{{ displayTime(row.created_at) }}</template></el-table-column><el-table-column prop="amount" label="金额"/><el-table-column label="状态"><template #default="{row}">{{ costLabel(row.state) }}</template></el-table-column><el-table-column label="方式"><template #default="{row}">{{ methodLabel(row.method) }}</template></el-table-column><el-table-column prop="reason" label="原因"/></el-table></div>
      <section class="spaced"><h4>当前成本 · {{ costLabel(context.latest_cost?.status) }} · 版本 {{ context.latest_cost?.sequence ?? '—' }}</h4><el-alert v-if="context.latest_cost?.status==='recalculation_required'" title="输入已变化，当前成本待复算。" type="warning" :closable="false"/><el-alert v-for="issue in (context.latest_cost?.issues||[])" :key="issue" :title="issue" type="info" :closable="false"/><p v-if="context.latest_cost">发货成本 {{ context.latest_cost.summary?.shipped_total ?? '—' }} · 收货成本 {{ context.latest_cost.summary?.received_total ?? '—' }} · 待处理 {{ context.latest_cost.summary?.pending_total ?? '—' }}</p>
        <el-button v-if="context.target?.calculation_allowed" type="primary" plain :disabled="busy||!canWrite" :loading="busy" @click="calculate">计算成本</el-button><p v-else-if="kind==='shipment' && (context.target?.calculation_kind==='batch' || context.target?.related_batches?.length)">该发货单已集货，请分别按发运批次计算成本。<span v-for="batch in (context.target?.related_batches || [])" :key="batch.batch_id"> {{ batch.batch_number }}：{{ batch.quantity }} 件；</span></p><el-table v-if="context.latest_cost?.entries?.length" :data="context.latest_cost.entries" border><el-table-column label="商品图片" width="112"><template #default="{row}"><DocumentProductImageV2 :image-path="row.image_preview_url || ''" :alt="`${row.sku || ''} 商品图片`"/></template></el-table-column><el-table-column label="SKU" min-width="190"><template #default="{row}"><DocumentSkuV2 :sku="row.sku" :legacy-sku-code="row.legacy_sku_code"/></template></el-table-column><el-table-column prop="quantity" label="发货数"/><el-table-column prop="received_quantity" label="实收数"/><el-table-column prop="goods_amount" label="商品金额" min-width="140"/><el-table-column prop="collection_fee" label="集货费" min-width="140"/><el-table-column prop="freight_fee" label="运费" min-width="140"/><el-table-column prop="clearance_fee" label="清货费" min-width="140"/><el-table-column prop="shipped_total" label="发货成本" min-width="140"/><el-table-column prop="received_total" label="收货成本" min-width="140"/><el-table-column prop="shipped_unit_cost" label="发货单件成本" min-width="140"/><el-table-column prop="received_unit_cost" label="入库单件成本" min-width="140"/><el-table-column prop="pending_total" label="待处理" min-width="140"/></el-table><el-table v-if="context.latest_cost?.adjustments?.length" :data="context.latest_cost.adjustments" border><el-table-column prop="previous_amount" label="调整前"/><el-table-column prop="current_amount" label="调整后"/><el-table-column prop="delta" label="差额"/></el-table><div v-if="context.cost_history?.length" class="table-scroll"><h5>历史成本版本</h5><el-table :data="context.cost_history" border><el-table-column prop="sequence" label="版本"/><el-table-column label="阶段"><template #default="{row}">{{ stageLabel(row.stage) }}</template></el-table-column><el-table-column label="状态"><template #default="{row}">{{ costLabel(row.status) }}</template></el-table-column><el-table-column label="时间"><template #default="{row}">{{ displayTime(row.created_at) }}</template></el-table-column><el-table-column label="明细"><template #default="{row}"><el-button link @click="loadVersion(row.sequence)">查看冻结明细</el-button></template></el-table-column></el-table></div><el-table v-if="selectedVersion?.entries?.length" :data="selectedVersion.entries" border><el-table-column label="历史版本"><template #default>{{ selectedVersion.sequence }}</template></el-table-column><el-table-column label="商品图片" width="112"><template #default="{row}"><DocumentProductImageV2 :image-path="row.image_preview_url || ''" :alt="`${row.sku || ''} 商品图片`"/></template></el-table-column><el-table-column label="SKU" min-width="190"><template #default="{row}"><DocumentSkuV2 :sku="row.sku" :legacy-sku-code="row.legacy_sku_code"/></template></el-table-column><el-table-column prop="quantity" label="发货数"/><el-table-column prop="received_quantity" label="实收数"/><el-table-column prop="goods_amount" label="商品金额" min-width="140"/><el-table-column prop="collection_fee" label="集货费" min-width="140"/><el-table-column prop="freight_fee" label="运费" min-width="140"/><el-table-column prop="clearance_fee" label="清货费" min-width="140"/><el-table-column prop="shipped_total" label="发货成本" min-width="140"/><el-table-column prop="received_total" label="收货成本" min-width="140"/><el-table-column prop="shipped_unit_cost" label="发货单件成本" min-width="140"/><el-table-column prop="received_unit_cost" label="入库单件成本" min-width="140"/></el-table></section>
      <section v-if="context.settlement_supported" class="spaced"><h4>结算登记</h4><p>累计登记 {{ context.settlement?.recorded_amount ?? '0.0000' }} · 未结算 {{ context.settlement?.unsettled_amount ?? '待核对' }} · {{ settlementLabel }}</p><p v-if="context.settlement?.adjustment_due">待对账差额 {{ context.settlement.adjustment_due }}</p><el-alert v-if="Number(context.settlement?.over_recorded_amount)>0" title="累计登记金额高于当前应结金额，请核对历史登记或成本调整。" type="warning" :closable="false"/><div v-if="canWrite" class="grid"><el-form-item label="累计已结算金额"><el-input :disabled="busy||loading" v-model="settlement.recorded_amount" inputmode="decimal"/></el-form-item><el-form-item label="参考单号"><el-input :disabled="busy||loading" v-model="settlement.reference_number"/></el-form-item><el-form-item label="日期"><el-date-picker :disabled="busy||loading" v-model="settlement.date" value-format="YYYY-MM-DD" type="date"/></el-form-item><el-form-item label="登记原因（必填）"><el-input :disabled="busy||loading" v-model="settlement.reason"/></el-form-item></div><el-form-item v-if="canWrite" label="备注"><el-input :disabled="busy||loading" v-model="settlement.notes"/></el-form-item><p class="hint">此处只登记结算金额，不会执行付款。</p><el-button v-if="canWrite" :disabled="busy" :loading="busy" @click="recordSettlement">保存结算登记</el-button><el-table v-if="context.settlement_history?.length" :data="context.settlement_history" border><el-table-column prop="recorded_amount" label="累计登记"/><el-table-column prop="reference_number" label="参考单号"/><el-table-column prop="date" label="日期"/><el-table-column prop="reason" label="原因"/></el-table></section>
    </template>
  </section>
</template>
<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue';
import { ElMessage } from 'element-plus';
import DocumentSkuV2 from './DocumentSkuV2.vue';
import DocumentProductImageV2 from './DocumentProductImageV2.vue';
import * as api from '../../api/supplyCostsV2';
import { useAuthStore } from '../../stores/auth';
const props=defineProps({kind:{type:String,required:true},id:{type:[String,Number],required:true},version:{type:[String,Number],default:0}}),emit=defineEmits(['updated']);
const auth=useAuthStore(),canWrite=computed(()=>!auth.authorizationStale&&auth.hasPermission('supply.v2.manage')),editable=computed(()=>canWrite.value&&context.value?.target?.fee_editable!==false),kindLabel=computed(()=>({shipment:'发货单',batch:'发运批次',inbound:'入库单'})[props.kind]||props.kind),settlementLabel=computed(()=>({unsettled:'未结算',partially_settled:'部分结算',settled:'已结算'})[context.value?.settlement?.status]||'未登记');
const loading=ref(false),busy=ref(false),error=ref(''),context=ref(null),fee=reactive({amount:'',state:'estimated',method:'volume',volume_percent:'50',billed_cbm:'',notes:'',reason:''}),measurements=ref([]),settlement=reactive({recorded_amount:'',reference_number:'',date:'',notes:'',reason:''}),keys=new Map(),savedSnapshot=ref(''),refreshPending=ref(false),selectedVersion=ref(null);
function snapshot(){return JSON.stringify({fee:{amount:fee.amount,state:fee.state,method:fee.method,volume_percent:fee.volume_percent,billed_cbm:fee.billed_cbm,notes:fee.notes},measurements:measurements.value.map(m=>({shipment_line_id:m.shipment_line_id,volume_cbm:m.volume_cbm,weight_kg:m.weight_kg})),settlement:{recorded_amount:settlement.recorded_amount,reference_number:settlement.reference_number,date:settlement.date,notes:settlement.notes}});}
const dirty=computed(()=>!!savedSnapshot.value&&snapshot()!==savedSnapshot.value);
function unwrap(r){if(!r?.success)throw new Error(r?.message||'请求失败');return r.data;}
function idempotent(slot,body,run){const f=JSON.stringify(body);let p=keys.get(slot);if(!p||p.f!==f){p={f,key:api.createIdempotencyKey()};keys.set(slot,p);}return run(p.key).then(r=>{const d=unwrap(r);keys.delete(slot);return d;});}
function hydrate(data){context.value=data;const f=data.fee||{};Object.assign(fee,{amount:f.amount==null?'':String(f.amount),state:f.state||'estimated',method:f.method||'volume',volume_percent:f.volume_percent==null?'50':String(f.volume_percent),billed_cbm:f.billed_cbm==null?'':String(f.billed_cbm),notes:f.notes||'',reason:''});measurements.value=(data.measurements||[]).map(m=>({...m,volume_cbm:m.volume_cbm==null?'':String(m.volume_cbm),weight_kg:m.weight_kg==null?'':String(m.weight_kg)}));const s=data.settlement||{};Object.assign(settlement,{recorded_amount:s.recorded_amount==null?'':String(s.recorded_amount),reference_number:s.reference_number||'',date:s.date||'',notes:s.notes||'',reason:''});refreshPending.value=false;selectedVersion.value=null;savedSnapshot.value=snapshot();emit('updated',data.target);}
async function load(){loading.value=true;error.value='';try{hydrate(unwrap(await api.fetchCostContext(props.kind,props.id)));}catch(e){error.value=e.message||'费用信息读取失败';}finally{loading.value=false;}}
function decimal(v,precision,label,required=false){const s=String(v??'').trim();if(!s&&!required)return null;if(!new RegExp(`^\\d+(?:\\.\\d{1,${precision}})?$`).test(s))throw new Error(`${label}需为非负数且最多 ${precision} 位小数。`);return s;}
function methodLabel(value){return ({volume:'按体积',weight:'按重量',mixed:'体积与重量混合'})[value]||'—';}
function stageLabel(value){return ({shipped:'发货阶段',received:'入库阶段'})[value]||'—';}
function displayTime(value){if(!value)return '—';const date=new Date(value);return Number.isNaN(date.getTime())?'—':date.toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});}
function costLabel(state){return ({estimated:'暂估',confirmed:'已确认',recalculation_required:'待重算'})[state]||'尚未计算';}
function measurementPayload(){return measurements.value.map(row=>{const original=context.value.measurements.find(m=>m.shipment_line_id===row.shipment_line_id)||{};const value=(name,source,label)=>{const parsed=decimal(row[name],6,label);return row[source]==='manual_total'||String(row[name]??'')!==String(original[name]??'')?parsed:null;};return {shipment_line_id:row.shipment_line_id,volume_cbm:value('volume_cbm','volume_source','本行总体积'),weight_kg:value('weight_kg','weight_source','本行总重量')};});}
async function saveFee(){if(!editable.value||busy.value)return;error.value='';try{if(!fee.reason.trim())throw new Error('请填写费用维护原因。');const body={expected_source_version:Number(context.value.target.version),expected_version:Number(context.value.fee?.version||0),amount:decimal(fee.amount,4,'费用金额',true),state:fee.state,method:fee.method,volume_percent:fee.method==='mixed'?decimal(fee.volume_percent,2,'体积分摊比例',true):null,billed_cbm:props.kind==='shipment'?null:decimal(fee.billed_cbm,6,'计费体积'),notes:fee.notes,reason:fee.reason.trim(),measurements:measurementPayload()};if(fee.method==='mixed'&&Number(body.volume_percent)>100)throw new Error('体积分摊比例不能超过 100%。');busy.value=true;await idempotent('fee',body,k=>api.saveFee(props.kind,props.id,body,k));await load();ElMessage.success('费用已保存。');}catch(e){error.value=e.message||'费用保存失败';}finally{busy.value=false;}}
async function calculate(){if(!canWrite.value||busy.value)return;const body={expected_source_version:Number(context.value.target.calculation_version),expected_input_fingerprint:context.value.input_fingerprint};busy.value=true;try{await idempotent('calculate',body,k=>api.calculateCost(context.value.target.calculation_kind,context.value.target.calculation_id,body,k));await load();ElMessage.success('成本已更新。');}catch(e){error.value=e.message||'成本计算失败';}finally{busy.value=false;}}
async function recordSettlement(){if(!canWrite.value||!context.value?.settlement_supported||busy.value)return;error.value='';try{if(!settlement.reason.trim())throw new Error('请填写结算登记原因。');const body={expected_source_version:Number(context.value.target.version),expected_version:Number(context.value.settlement?.version||0),recorded_amount:decimal(settlement.recorded_amount,4,'累计已结算金额',true),reference_number:settlement.reference_number,date:settlement.date,notes:settlement.notes,reason:settlement.reason.trim()};busy.value=true;await idempotent('settlement',body,k=>api.recordSettlement(props.kind,props.id,body,k));await load();ElMessage.success('结算登记已保存。');}catch(e){error.value=e.message||'结算登记失败';}finally{busy.value=false;}}
async function loadVersion(sequence){error.value='';try{selectedVersion.value=unwrap(await api.fetchCostVersion(props.kind,props.id,sequence));}catch(e){error.value=e.message||'历史成本版本读取失败';}}
watch(()=>[props.kind,props.id],load);watch(()=>props.version,version=>{if(!context.value||String(version)===String(context.value.target?.version))return;if(dirty.value){refreshPending.value=true;return;}load();});onMounted(load);
defineExpose({load,loadVersion,saveFee,calculate,recordSettlement,context,fee,measurements,settlement,selectedVersion,refreshPending,dirty});
</script>
<style scoped>.cost-panel{margin:18px 0}.spaced{margin-top:16px}.fee-form{margin-top:18px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:8px}.table-scroll{overflow-x:auto;margin:12px 0}.table-scroll :deep(.el-table){min-width:720px}.hint{color:#64748b;font-size:12px}h4{margin:12px 0}</style>
